async function createOutputDirs(matchedPairs, outputDir) {
  await ensureDirectory(outputDir);
  const categories = [...new Set(matchedPairs.map((p) => p.Category).filter(Boolean))];
  for (const category of categories) {
    const categoryDir = path8.join(outputDir, category);
    await ensureDirectory(categoryDir);
    const departments = [
      ...new Set(matchedPairs.filter((p) => p.Category === category).map((p) => p.Department).filter(Boolean))
    ];
    for (const department of departments) {
      const departmentDir = path8.join(categoryDir, department);
      await ensureDirectory(departmentDir);
      const assetsDir = path8.join(departmentDir, "assets");
      await ensureDirectory(assetsDir);
    }
  }
}

